project_task.solution:
def move(pos, direction):
    x, y = pos
    if direction == "north":
        y += 1
    elif direction == "south":
        y -= 1
    elif direction == "east":
        x += 1
    elif direction == "west":
        x -= 1
    return (x, y)

print(move((0, 0), "north"))
